export function getProfessionData(professionKey: string): IProfessionData {
  const data = professions[professionKey.toLowerCase().replace(' ', '_')];
  if (!data) {
    throw new Error(`Invalid profession key: ${professionKey}`);
  }
  return data;
}

export function getAllProfessions(): string[] {
  return Object.keys(professions);
}

export function getProfessionNames(): string[] {
  return Object.values(professions).map((p) => p.name);
}
